INSERT INTO `v1_cf6de999ba6c6b27cba8c5eed04c8254ced99f91a8a63f180a2861d8e3aa2ccc` VALUES (1, "イベントでは、特別なストーリーをお楽しみいただけます。\n閲覧可能なストーリーを読むと、次のお話が解放されていきますよ。\nストーリーの閲覧によって達成されるミッションもあるのだとか。", 1, 1011, 1);
INSERT INTO `v1_cf6de999ba6c6b27cba8c5eed04c8254ced99f91a8a63f180a2861d8e3aa2ccc` VALUES (2, "イベントクエストやボスバトルに挑戦してみましょう。ボスバトルは\n特定のイベントストーリーを閲覧するか、イベントクエスト・ボス画面で\n「解放する」を選択すると挑戦可能になりますよ。", 1, 1021, 2);
INSERT INTO `v1_cf6de999ba6c6b27cba8c5eed04c8254ced99f91a8a63f180a2861d8e3aa2ccc` VALUES (4, "報酬交換では「イベント報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 1, 1041, 4);
INSERT INTO `v1_cf6de999ba6c6b27cba8c5eed04c8254ced99f91a8a63f180a2861d8e3aa2ccc` VALUES (5, "ボスバトルには３種の難易度がございます。\n各難易度ごとにボスの強さやバトルの特徴が異なりますので、\n準備をしっかりして、気を引き締めて挑みましょう。", 1, 1051, 5);
INSERT INTO `v1_cf6de999ba6c6b27cba8c5eed04c8254ced99f91a8a63f180a2861d8e3aa2ccc` VALUES (1, "イベントでは、特別なストーリーをお楽しみいただけます。\n閲覧可能なストーリーを読むと、次のお話が解放されていきますよ。", 2, 2011, 1);
INSERT INTO `v1_cf6de999ba6c6b27cba8c5eed04c8254ced99f91a8a63f180a2861d8e3aa2ccc` VALUES (2, "イベントクエストやボスバトルに挑戦してみましょう。ボスバトルは\n特定のイベントストーリーを閲覧するか、イベントクエスト・ボス画面で\n「解放する」を選択すると挑戦可能になりますよ。", 2, 2021, 2);
INSERT INTO `v1_cf6de999ba6c6b27cba8c5eed04c8254ced99f91a8a63f180a2861d8e3aa2ccc` VALUES (4, "報酬交換では「イベント報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 2, 2041, 4);
INSERT INTO `v1_cf6de999ba6c6b27cba8c5eed04c8254ced99f91a8a63f180a2861d8e3aa2ccc` VALUES (5, "ボスバトルには２種の難易度がございます。\n各難易度ごとにボスの強さやバトルの特徴が異なりますので、\n準備をしっかりして、気を引き締めて挑みましょう。", 2, 2051, 5);
